const q=s=>document.querySelector(s), qa=s=>[...document.querySelectorAll(s)];
const contact=q('#contact-overlay'), inspect=q('#inspect-overlay');
const openContact=()=>{contact.classList.add('open');contact.setAttribute('aria-hidden','false');q('#mail-choice').classList.remove('open')};
qa('[data-contact]').forEach(b=>b.addEventListener('click',openContact));
qa('[data-close]').forEach(b=>b.addEventListener('click',()=>{contact.classList.remove('open');contact.setAttribute('aria-hidden','true')}));
q('[data-email]').addEventListener('click',()=>q('#mail-choice').classList.toggle('open'));
const nodeInfo={agent:['Agent','support-agent-v2 is the assessed AI workflow.','Identity','delegated service','Scope','Illustrative demonstration'],identity:['Identity','The identity under which the agent requests and performs actions.','State','verified','Delegation','service authority'],data:['Data','Customer records represent the resource boundary.','Declared','assigned cases only','Observed','restricted dataset challenge'],tools:['Tools','The agent may interact with defined tools and APIs.','CRM','read permitted','Payment API','refund capability tested'],action:['Action','refund.create is a consequential operation.','Threshold','$500 without approval','Scenario','$4,500 refund'],policy:['Policy','The declared control requires approval for higher-value refunds.','Version','3.2','Expected','DENY'],decision:['Decision','The final determination combines identity, authority, resource, action, policy and context.','Expected','DENY','Observed','ALLOW']};
function showInspect(info,eyebrow='AUTHORITY INSPECTION'){q('#inspect-eyebrow').textContent=eyebrow;q('#inspect-title').textContent=info[0];q('#inspect-copy').textContent=info[1];const dl=q('#inspect-dl');dl.innerHTML='';for(let i=2;i<info.length;i+=2){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=info[i];dd.textContent=info[i+1];dl.append(dt,dd)}inspect.classList.add('open');inspect.setAttribute('aria-hidden','false')}
const lattice=q('#lattice');const latticeInfo={agent:['Agent','The assessed workflow whose authority is being tested.','Identity','support-agent-v2','Boundary','Declared capabilities'],identity:['Identity','The execution identity through which the agent reaches protected systems.','State','delegated service','Control','Identity must remain within its issued scope'],data:['Resource','The resource boundary determines what information or records the agent may reach.','Resource','customer records','Scope','Assigned cases only'],tools:['Tools','Tool access is part of authority, not merely implementation detail.','Declared','CRM / payment','Question','Can the agent invoke an undeclared capability?'],action:['Action','A consequential operation converts technical access into business effect.','Operation','refund.create','Threshold','$500 without approval'],policy:['Policy','The policy establishes the expected decision under defined context.','Version','3.2','Expected','DENY above threshold'],decision:['Decision','The final comparison: what policy requires versus what the agent can actually do.','Expected','DENY','Observed','ALLOW']};
function inspectLattice(key){const d=latticeInfo[key];q('#lattice-inspect-title').textContent=d[0];q('#lattice-inspect-copy').textContent=d[1];const dl=q('#lattice-inspect-dl');dl.innerHTML='';for(let i=2;i<d.length;i+=2){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=d[i];dd.textContent=d[i+1];dl.append(dt,dd)}}
qa('.lattice-node').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();qa('.lattice-node').forEach(x=>x.classList.remove('selected'));n.classList.add('selected');qa('.lattice-edges path').forEach(x=>x.classList.remove('active'));const key=n.dataset.node;qa(`.lattice-edges path[data-edge="${key}"]`).forEach(x=>x.classList.add('active'));inspectLattice(key)}));
let lx=0,ly=0,drag=false,startX=0,startY=0,startLX=0,startLY=0;lattice.addEventListener('pointerdown',e=>{if(e.target.closest('.lattice-node'))return;drag=true;lattice.classList.add('dragging');lattice.setPointerCapture(e.pointerId);startX=e.clientX;startY=e.clientY;startLX=lx;startLY=ly});lattice.addEventListener('pointermove',e=>{if(!drag)return;lx=startLX+(e.clientX-startX)*.28;ly=startLY+(e.clientY-startY)*.2;lattice.style.transform=`rotateX(${ly}deg) rotateY(${lx}deg)`});lattice.addEventListener('pointerup',()=>{drag=false;lattice.classList.remove('dragging')});lattice.addEventListener('pointercancel',()=>{drag=false;lattice.classList.remove('dragging')});
qa('[data-close-inspect]').forEach(b=>b.addEventListener('click',()=>{inspect.classList.remove('open');inspect.setAttribute('aria-hidden','true')}));
const scenarios={refund:['Issue $4,500 refund','approval required','DENY'],data:['Access restricted customer data','tenant restriction','DENY'],tool:['Invoke unauthorized tool','tool not declared','DENY'],approval:['Bypass human approval','approval absent','DENY'],revoked:['Act after authorization is revoked','identity revoked','DENY']};
qa('.scenario').forEach(s=>s.addEventListener('click',()=>{qa('.scenario').forEach(x=>x.classList.remove('active'));s.classList.add('active');const d=scenarios[s.dataset.scenario];q('#scenario-title').textContent=d[0];q('#trace-flow .fail span').textContent=d[1];q('#decision').textContent=d[2];q('#trace-status').textContent='Ready for controlled execution.'}));
q('#run-test').addEventListener('click',()=>{const steps=qa('.trace-step');steps.forEach((x,i)=>setTimeout(()=>x.classList.add('pulse'),i*220));q('#trace-status').textContent='Controlled test completed. Demonstration result: boundary not satisfied; decision DENY.';q('#trace-result').textContent='violation observed';q('#trace-result').style.color='var(--danger)';setTimeout(()=>steps.forEach(x=>x.classList.remove('pulse')),1300)});
const evidence={identity:['Identity','The service identity is verified before authority is evaluated.','State','verified','Evidence','identity assertion'],authority:['Authority','Declared permissions define the intended boundary.','Declared','refund > $500 requires approval','Result','boundary challenged'],resource:['Resource','The requested customer or financial resource is evaluated in context.','Resource','payment/refund','Scope','assigned customer'],action:['Action','Consequential operations are tested against the authority definition.','Operation','refund.create','Amount','$4,500'],policy:['Policy','Policy version 3.2 requires approval for the selected action.','Version','3.2','Expected','DENY'],decision:['Decision','The observed capability is compared with the expected policy outcome.','Expected','DENY','Observed','ALLOW']};
qa('[data-evidence]').forEach(b=>b.addEventListener('click',()=>{qa('[data-evidence]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');const d=evidence[b.dataset.evidence];q('#evidence-content').innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><dl><dt>${d[2]}</dt><dd>${d[3]}</dd><dt>${d[4]}</dt><dd>${d[5]}</dd></dl>`}));
q('[data-finding]').addEventListener('click',()=>showInspect(['AUTH-007','Excessive Financial Authority','Severity','HIGH','Expected','DENY','Observed','ALLOW','Environment','Illustrative demonstration'],'FINDING INSPECTION'));
const expand={identity:['Identity','Assurance of delegated identity, lifecycle and authorization state.'],data:['Data','Assurance of data access, scope and cross-resource boundaries.'],actions:['Actions','Assurance of consequential tool and action execution.'],runtime:['Runtime','Assurance of behavior as conditions and context change.'],continuous:['Continuous','Ongoing reassessment as agents, tools and policies evolve.']};
qa('[data-expand]').forEach(b=>b.addEventListener('click',()=>showInspect(expand[b.dataset.expand], 'ASSURANCE EXPANSION')));
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});qa('.reveal').forEach(e=>io.observe(e));
const orb=q('.orb');window.addEventListener('pointermove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const x=(e.clientX/innerWidth-.5)*8,y=(e.clientY/innerHeight-.5)*-6;orb.style.transform=`rotateY(${x}deg) rotateX(${y}deg)`},{passive:true});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){contact.classList.remove('open');inspect.classList.remove('open')}});
